"""The schedule a retrying client would follow. See task.md."""

from __future__ import annotations

from fractions import Fraction

# A recorded response: {"status": int, "retry_after_ms": int}  (the second key
# is optional).
Response = dict

# A planned attempt: {"number": int, "start_ms": int, "delay_ms": int}.
Attempt = dict

RETRYABLE_STATUSES = frozenset({429, 500, 502, 503})
SUCCESS_STATUS = 200


class PolicyError(ValueError):
    """Raised for a policy or deadline that cannot describe a schedule."""


def _parse_factor(factor) -> Fraction:
    if isinstance(factor, list):
        numerator, denominator = factor
        if denominator <= 0 or numerator < denominator:
            raise PolicyError(f"factor {factor!r} must be at least 1")
        return Fraction(numerator, denominator)
    if factor < 1:
        raise PolicyError(f"factor {factor!r} must be at least 1")
    return Fraction(factor)


def plan(policy: dict, responses: list[Response], deadline_ms: int) -> list[Attempt]:
    """Return the attempts a client under `policy` would make against `responses`."""
    base_ms = policy["base_ms"]
    max_delay_ms = policy["max_delay_ms"]
    max_attempts = policy["max_attempts"]

    if base_ms <= 0:
        raise PolicyError(f"base_ms {base_ms!r} must be positive")
    factor = _parse_factor(policy["factor"])
    if max_attempts < 1:
        raise PolicyError(f"max_attempts {max_attempts!r} must be at least 1")
    if deadline_ms < 0:
        raise PolicyError(f"deadline_ms {deadline_ms!r} must not be negative")

    attempts: list[Attempt] = []
    start_ms = 0
    delay_ms = 0
    for number in range(1, max_attempts + 1):
        if number > len(responses):
            break
        if number > 1:
            previous = responses[number - 2]
            if previous["status"] in RETRYABLE_STATUSES and "retry_after_ms" in previous:
                delay_ms = previous["retry_after_ms"]
            else:
                backed = int(base_ms * factor ** (number - 2))
                delay_ms = min(backed, max_delay_ms)
            start_ms += delay_ms
        if start_ms >= deadline_ms:
            break

        attempts.append({"number": number, "start_ms": start_ms, "delay_ms": delay_ms})
        status = responses[number - 1]["status"]
        if status == SUCCESS_STATUS or status not in RETRYABLE_STATUSES:
            break

    return attempts
